SELECT m.movie_asin, m.movie_title, m.score, concat_ws(',', collect_list(a.name)) AS actors, concat_ws(',', collect_list(d.name)) AS directors, concat_ws(',', collect_list(mg.genre)) AS genres, concat(rd.year, '-', lpad(rd.month, 2, '0'), '-', lpad(rd.day, 2, '0')) AS release_date, concat_ws(',', collect_list(me.edition)) AS editions FROM movies m LEFT JOIN movie_actors ma ON m.id = ma.movie_id LEFT JOIN actors a ON ma.actor_id = a.id LEFT JOIN movie_directors md ON m.id = md.movie_id LEFT JOIN directors d ON md.director_id = d.id LEFT JOIN movie_genres mg ON m.id = mg.movie_id LEFT JOIN release_dates rd ON m.id = rd.movie_id LEFT JOIN movie_editions me ON m.id = me.movie_id
m.movie_title LIKE CONCAT('%', ${dto.movieTitle}, '%')
AND a.name LIKE CONCAT('%', ${dto.actorName}, '%')
AND d.name LIKE CONCAT('%', ${dto.directorName}, '%')
AND array_contains(collect_set(mg.genre), '${dto.movieGenre}')
AND rd.year >= ${dto.startYear}
AND rd.year <= ${dto.endYear}
AND rd.month = ${dto.month}
AND rd.day = ${dto.day}
AND m.score >= ${dto.minScore}
AND m.score <= ${dto.maxScore}
GROUP BY m.id, m.movie_asin, m.movie_title, m.score, rd.year, rd.month, rd.day ORDER BY m.movie_title
LIMIT ${dto.size} OFFSET ${dto.page}

SELECT m.id
FROM movies m

    INNER JOIN (
        SELECT DISTINCT ma.movie_id 
        FROM movie_actors ma 
        JOIN actors a ON ma.actor_id = a.id 
        WHERE LOWER(a.name) LIKE CONCAT('%', #{dto.movieTitle}, '%') 
    ) a_filt ON m.id = a_filt.movie_id


    INNER JOIN (
        SELECT DISTINCT md.movie_id 
        FROM movie_directors md 
        JOIN directors d ON md.director_id = d.id 
        WHERE LOWER(d.name) LIKE CONCAT('%', #{dto.directorName}, '%')
    ) d_filt ON m.id = d_filt.movie_id


    INNER JOIN (
        SELECT DISTINCT mg.movie_id 
        FROM movie_genres mg 
        WHERE LOWER(mg.genre) LIKE CONCAT('%', #{dto.movieGenre}, '%')
    ) g_filt ON m.id = g_filt.movie_id


    INNER JOIN (
        SELECT movie_id 
        FROM release_dates rd 
        WHERE 1=1
        AND rd.year >= #{dto.startYear}
        AND rd.year <= #{dto.endYear}
        AND rd.month = #{dto.month}
        AND rd.day = #{dto.day}
    ) r_filt ON m.id = r_filt.movie_id



        AND LOWER(m.movie_title) LIKE CONCAT('%', #{dto.movieTitle}, '%')


    AND m.score >= #{dto.minScore}


    AND m.score <= #{dto.maxScore}


ORDER BY m.movie_title

    LIMIT #{dto.size} OFFSET #{dto.page}

