SELECT 
    movie_asin AS movieasin,
    movie_title AS movietitle,
    movie_score AS moviescore,
    concat_ws(',', actor_names) AS actors,
    concat_ws(',', director_names) AS directors,
    concat_ws(',', movie_genres) AS moviegenre,
    CAST(release_date AS STRING) AS release_date,
    concat_ws(',', edition_list) AS edition
FROM movie_denormalization



        AND release_year >= #{dto.startYear}


        AND release_year <= #{dto.endYear}



        AND LOWER(movie_title) LIKE CONCAT('%', LOWER(#{dto.movieTitle}), '%')



        AND array_contains(actor_names, #{dto.actorName})


        AND array_contains(director_names, #{dto.directorName})


        AND array_contains(movie_genres, #{dto.movieGenre})


    AND release_month = #{dto.month}
    AND release_day = #{dto.day}
    AND movie_score >= #{dto.minScore}
    AND movie_score <= #{dto.maxScore}

ORDER BY movietitle

    LIMIT #{dto.size} OFFSET #{dto.page}

SELECT m.movie_asin, m.movie_title, m.score, concat_ws(',', collect_list(a.name)) AS actors, concat_ws(',', collect_list(d.name)) AS directors, concat_ws(',', collect_list(mg.genre)) AS genres, concat(rd.year, '-', lpad(rd.month, 2, '0'), '-', lpad(rd.day, 2, '0')) AS release_date, concat_ws(',', collect_list(me.edition)) AS editions FROM movies_ext m LEFT JOIN movie_actors_ext ma ON m.id = ma.movie_id LEFT JOIN actors_ext a ON ma.actor_id = a.id LEFT JOIN movie_directors_ext md ON m.id = md.movie_id LEFT JOIN directors_ext d ON md.director_id = d.id LEFT JOIN movie_genres_ext mg ON m.id = mg.movie_id LEFT JOIN release_dates_ext rd ON m.id = rd.movie_id LEFT JOIN movie_editions_ext me ON m.id = me.movie_id
AND LOWER(m.movie_title) LIKE CONCAT('%', LOWER(#{dto.movieTitle}), '%')
AND LOWER(a.name) LIKE CONCAT('%', LOWER(#{dto.actorName}), '%')
AND LOWER(d.name) LIKE CONCAT('%', LOWER(#{dto.directorName}), '%')
AND LOWER(mg.genre) LIKE CONCAT('%', LOWER(#{dto.movieGenre}), '%')
AND rd.year >= #{dto.startYear}
AND rd.year <= #{dto.endYear}
AND rd.month = #{dto.month}
AND rd.day = #{dto.day}
AND m.score >= #{dto.minScore}
AND m.score <= #{dto.maxScore}
GROUP BY m.id, m.movie_asin, m.movie_title, m.score, rd.year, rd.month, rd.day ORDER BY m.movie_title
LIMIT #{dto.size} OFFSET #{dto.page}
